/* ============================================================================
   art.js — window.BVArt
   Bifrost Vault commercial · coin FRAME + metal rendering + every prop.
   The six coin ILLUSTRATIONS come from window.BVArtFields (art-fields.js,
   loaded before this file); this module turns them into struck, proof-finish
   coins (silver or gold), builds the shared reverse, the 3D coin mount, the
   holographic Vault Pack and all props.

   TYPE: every word drawn inside an SVG is converted to vector outlines at build
   time from Space Grotesk 600/700 and JetBrains Mono Medium (both SIL Open Font
   License 1.1, glyph subset embedded below). SVG-as-<img> cannot use page web
   fonts, so outlines are the only way legends render identically everywhere
   (headless render, offline, any browser) — crisp at any size, no font wait.

   API (all sizes in px, all angles in degrees)
   --------------------------------------------------------------------------
   COINS                 [{ id, name, legend, series, tier, rarity, metal:'ag'|'au',
                            oz, grams, purity, metalLabel, weightLabel, legendBottom,
                            edition, mintage, editionLabel, editionShort, year, artist,
                            palette, value }]
   COIN                  { [id]: coin }   (lookup)
   RARITY / TIERS        keyed by tier id ('silver'|'rare'|'gold'|'legendary') AND by
                         rarity key ('common'|'rare'|'epic'|'legendary'):
                         { id, label, short, color, glow, rgb, metal, aurora:bool, shadow(px, k) }
   AURORA                ['#7C5CFF','#4D8DFF','#19D3FF','#46E6A6']

   coinSVG(id, {side:'face'|'reverse', size=1024, serial, edition:true, mint:true}) -> <svg> string
       Field composition: BVArtFields[id].field (colour ink, clipped r<=330) masked by inkMask over the
       polished metal, soft-light metal sheen + enamel gloss, relief -> frosted cameo + diffuse/specular
       emboss. Optional BVArtFields[id].over(uid): markup drawn above the band (rim-breaking strikes).
       A missing / failing illustration renders an engraved guilloche placeholder.
   coinImg(id, {side='face', size=1024, serial}) -> HTMLImageElement (raster, cached)
   mountCoin(parent, id, {size=512, side, thickness, perspective, res, tier, edges})
       -> { el, rot, front, back, size, set({x,y,s,rx,ry,rz,o,glow,glint,glintA}),
            flipTo(deg), setCoin(id), setTier(tier), state }
       el is absolutely positioned; (x,y) is the coin CENTRE in parent px. Unspecified
       fields keep their previous value. glow: rarity rim-glow 0..1.5; glint: specular
       band angle (deg, e.g. tie to ry) with glintA (0..1) strength.
   packSVG({side:'front'|'back', size=760, seed=7, sealed=true, foil=0}) -> <svg> 760x1080 units
   packParts({side='front', size=760, seed=7}) -> { topSVG, bodySVG, tearPath, tearPoints, tearY, W, H }
   packFoil(angleDeg, {alpha=.6, at='50% 40%'}) -> CSS conic-gradient string (animate foil angle)
   packMask() -> CSS url(...) of the pack silhouette (for mask-image on foil overlays)
   mountPack(parent, {size=760, seed, perspective}) -> { el, rot, front, back, set({x,y,s,rx,ry,rz,o,foil,foilA,sheen}) }
   logoSVG({size=600, wordmark=true, layout:'row'|'stack', mono}) -> string
   markSVG({size=120}) -> string (arc mark only)
   certSVG(id, {serial, tx, owner, size=600, mini=false}) -> hex certificate token (600x692 units)
   nfcSVG({size=120, color='#46E6A6'}) -> string
   sealSVG(id, {size=240}) -> round holographic NFC seal sticker
   capsuleSVG(id|null, {size=600, layer:'full'|'back'|'front'}) -> acrylic capsule (600x600 units)
   boxSVG({open=0..1|bool, size=800, tape=true}) -> isometric matte-black box, aurora foam insert
                         (800x780 units; flaps fold out with open, closed variant has the tape strip)
   labelSVG({size=520}) -> shipping label 'TRACKED · NFC-SEALED' (520x300 units)
   phoneSVG(screenMarkup?, {size=380, hole=false}) -> phone frame 380x780 units; PHONE.screen = {x,y,w,h,r}
   vaultDoorSVG({open=0, size=1000, wheel=true, glow=1}) -> circular vault door (1000x1000 units)
   vaultWheelSVG({size=1000}) -> the 8-spoke wheel alone (same 1000 box, centred) for spinning
   textSVG(str, {x,y,size,font:'sg6'|'sg7'|'mono',anchor,tracking,fill}) -> outlined text <g>
   textWidth(str, {size,font,tracking}) -> px
   img(svg, {raster:false|true|px, scale, w, h}) -> HTMLImageElement. SVGs containing <filter> are
                         rasterised to a bitmap by default (cheap to transform every frame); pass
                         {raster:px} for a larger bitmap or {raster:false} to keep a vector <img>.
   packImg({side, seed, size, sealed, part:'top'|'body'}) -> rasterised pack <img> (front/back/parts pre-decoded)
   svgURI(svg) -> data URI
   prepare([{id, side, size}] | promise...) -> Promise (pre-raster extra coin sizes)
   ready -> Promise: 6 faces + 6 reverses @1024 (+ heimdall @2048) + pack front/back/parts decoded.
            Registered with BV.preload(BVArt.ready) when window.BV exists.
   ========================================================================== */
